/* Actual fd/hash/offset/ownership checks with own generated bytes. MIT. */
#define _GNU_SOURCE
#include <assert.h>
#include <dirent.h>
#include <openssl/evp.h>
#include <stdio.h>
#include "deck_font_files.h"

int linux_sha256_hex(const void *a, size_t na, const void *b, size_t nb, char out[65]) {
    unsigned char digest[32]; unsigned count = 0;
    EVP_MD_CTX *ctx = EVP_MD_CTX_new();
    int ok = ctx && EVP_DigestInit_ex(ctx, EVP_sha256(), NULL) == 1 && EVP_DigestUpdate(ctx, a, na) == 1 &&
        (!nb || EVP_DigestUpdate(ctx, b, nb) == 1) && EVP_DigestFinal_ex(ctx, digest, &count) == 1 && count == 32;
    EVP_MD_CTX_free(ctx);
    if (ok) for (unsigned i = 0; i < 32; i++) snprintf(out + i * 2, 3, "%02x", digest[i]);
    return ok;
}
static void hash_bytes(const void *p, size_t n, uint8_t out[32]) {
    char h[65]; assert(linux_sha256_hex(p, n, NULL, 0, h));
    for (unsigned i = 0; i < 32; i++) { unsigned x; assert(sscanf(h + i * 2, "%2x", &x) == 1); out[i] = (uint8_t)x; }
}
static void put64(uint8_t *p, uint64_t n) { for (unsigned i = 0; i < 8; i++) p[i] = (uint8_t)(n >> (8 * i)); }
static void write_file(const char *name, const void *p, size_t n) {
    int fd = open(name, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0600); assert(fd >= 0);
    assert(write(fd, p, n) == (ssize_t)n); assert(!close(fd));
}
static int fd_count(void) {
    DIR *d = opendir("/proc/self/fd"); assert(d); int n = 0;
    while (readdir(d)) n++;
    closedir(d); return n;
}
int main(void) {
    const char old[] = "own original compressed fixture", newer[] = "own newer fixture with DIFFERENT size";
    uint8_t header[ND_DECK_RESOURCE_HEADER] = "NDUIF002";
    put64(header + 8, sizeof old); put64(header + 16, sizeof newer);
    hash_bytes(old, sizeof old, header + 24); hash_bytes(newer, sizeof newer, header + 56);
    write_file("fonts.bin", header, sizeof header); write_file("0.zs", newer, sizeof newer);
    const uint64_t offset = 17;
    uint8_t packed[17 + sizeof old]; memset(packed, 0x5a, 17); memcpy(packed + 17, old, sizeof old);
    write_file("original", packed, sizeof packed);
    int source = open("original", O_RDONLY); assert(source >= 0);
    assert(nd_font_index(nd_font_paths[0]) == 0 && nd_font_index("Font/../../escape") == -1);
    uint64_t size = 0; int baseline = fd_count();
    for (int i = 0; i < 500; i++) {
        int fd = nd_font_open(".", 0, source, offset, sizeof old, &size); assert(fd >= 0 && size == sizeof newer);
        char result[sizeof newer]; assert(nd_font_read(fd, result, size, 0)); assert(!memcmp(result, newer, size));
        assert(fcntl(fd, F_GETFD) & FD_CLOEXEC); close(fd);
    }
    assert(fd_count() == baseline); assert(fcntl(source, F_GETFD) >= 0);
    assert(nd_font_open(".", -1, source, offset, sizeof old, &size) < 0);
    assert(nd_font_open(".", ND_DECK_RESOURCE_COUNT, source, offset, sizeof old, &size) < 0);
    assert(nd_font_open(".", 0, source, offset + 1, sizeof old, &size) < 0);
    assert(nd_font_open(".", 0, source, offset, sizeof old + 1, &size) < 0);
    write_file("0.zs", "corrupt", 7);
    assert(nd_font_open(".", 0, source, offset, sizeof old, &size) < 0);
    assert(!unlink("0.zs") && !symlink("original", "0.zs"));
    assert(nd_font_open(".", 0, source, offset, sizeof old, &size) < 0);
    assert(!unlink("0.zs") && !mkfifo("0.zs", 0600));
    assert(nd_font_open(".", 0, source, offset, sizeof old, &size) < 0);
    assert(!unlink("0.zs")); write_file("0.zs", newer, sizeof newer);
    header[0] = 'X'; write_file("fonts.bin", header, sizeof header);
    assert(nd_font_open(".", 0, source, offset, sizeof old, &size) < 0);
    write_file("fonts.bin", header, 12);
    assert(nd_font_open(".", 0, source, offset, sizeof old, &size) < 0);
    assert(fd_count() == baseline); close(source);
    puts("Deck font fd/offset/size/hash/ownership/symlink/FIFO guards passed; 500 opens without leaks");
    return 0;
}
